<?php
namespace App\Console\Commands; use Illuminate\Console\Command; use App\Models\Customer; use App\Services\IsolationService; use App\Services\FonnteService;
class IsolateOverdueCustomers extends Command {protected $signature='billing:isolate-overdue';protected $description='Isolir pelanggan melewati jatuh tempo + grace';public function handle(IsolationService $isolation,FonnteService $wa):int{$today=now(config('billing.timezone'))->startOfDay();$n=0;Customer::with(['router','package'])->where('status','active')->where('is_auto_isolate',true)->whereHas('invoices',function($q)use($today){$q->where('status','unpaid')->whereRaw('DATE_ADD(due_date, INTERVAL COALESCE((SELECT grace_days FROM customers WHERE customers.id = invoices.customer_id), ?) DAY) < ?', [config('billing.grace_days'),$today->toDateString()]);})->chunkById(100,function($customers)use($isolation,$wa,&$n){foreach($customers as $c){try{$isolation->isolate($c);$n++;$number=$c->whatsapp_number?:$c->phone;
$serviceUsername=$c->service_type==='pppoe'?$c->pppoe_username:$c->hotspot_username;
if($number)$wa->queue($c->id,$number,"Yth. {$c->name}, layanan internet Anda telah diisolir sementara karena tagihan belum dibayar. Silakan selesaikan pembayaran agar layanan dapat dipulihkan. ID pelanggan: {$c->customer_code}. Username layanan: {$serviceUsername}. Portal pelanggan: ".route('portal.login')." (ID login: {$c->customer_code}). Terima kasih.",'isolation',['name'=>$c->name,'customer_code'=>$c->customer_code,'portal_username'=>$c->customer_code,'service_username'=>$serviceUsername,'pppoe_username'=>$c->pppoe_username,'portal_url'=>route('portal.login')]);}catch(\Throwable $e){report($e);}}});$this->info("{$n} pelanggan diisolir dan notifikasi masuk antrean.");return self::SUCCESS;}}
